<script setup>
import { computed, onMounted, onUnmounted, ref, watch } from 'vue'
import { api, trackKey } from './api'
import Artwork from './Artwork.vue'
import Icon from './Icon.vue'
const props = defineProps({ playlists: {type:Array,default:()=>[]}, favorites:{type:Array,default:()=>[]}, initialId:{type:String,default:''} })
const emit = defineEmits(['play','update-local','download'])
const showCount = ref(100), filter = ref(''), loaded = ref(false), snapshotLoaded = ref(false)
const remote = ref({playlists:[]}), summary = ref({}), selectedId = ref(props.initialId), newName = ref(''), busy = ref(false), error = ref('')
let timer, polling = false
const lists = computed(() => [
  {id:'local:favorites',name:'本地喜欢',kind:'local',tracks:props.favorites.filter(t=>typeof t==='object')},
  ...props.playlists.map(p=>({...p,kind:'local'})), ...(remote.value.playlists || [])
])
const selected = computed(() => lists.value.find(p=>p.id===selectedId.value))
const kindLabel = kind => ({likes:'QQ · 我喜欢',owned:'QQ · 自建歌单',collected:'QQ · 收藏歌单',local:'本地歌单'})[kind]
const normalized = track => track.local ? track : {...track,title:track.name,artist:(track.artistName || []).join(' / '),album:track.albumName || '',coverUrl:track.pic,local:false}
const songs = computed(() => (selected.value?.tracks || []).map(normalized))
const matchingSongs = computed(() => songs.value.filter(t => `${t.title} ${t.artist} ${t.album}`.toLowerCase().includes(filter.value.toLowerCase())))
const visibleSongs = computed(() => matchingSongs.value.slice(0,showCount.value))
watch(()=>props.initialId,id=>{if(id)selectedId.value=id})
watch(selectedId, () => {filter.value='';showCount.value=100})
const syncError = computed(() => ({DOWNLOAD_QUEUE_PARTIAL:`${summary.value.queueFailures || 0} 首歌曲未能加入下载，其余任务正常继续，下次同步会重试。`,QQ_LOGIN_REQUIRED:'QQ 登录已过期，请到账号设置重新扫码。',QQ_NETWORK_UNAVAILABLE:'QQ 接口暂时未响应，会在下次定时同步重试。',QQ_COLLECTION_INCOMPLETE:'QQ 返回的歌单不完整，已保留上次完整歌单，下次自动重试。',COLLECTION_LIMIT_REACHED:'本次同步达到处理上限，已保留上次完整歌单。',QQ_COLLECTION_UNAVAILABLE:'QQ 暂未提供完整歌单，已保留上次结果，可立即重试。'})[summary.value.error] || summary.value.error)
async function load() { remote.value = await api('/listening/collection'); summary.value = {...remote.value}; loaded.value = true; snapshotLoaded.value = true; error.value = ''; if(!selectedId.value) selectedId.value = remote.value.playlists?.[0]?.id || lists.value[0]?.id }
async function poll() {
  if(polling) return;polling = true
  try { const status = await api('/listening/collection/status'); const changed = status.lastSuccess !== summary.value.lastSuccess; summary.value = status; loaded.value = true; error.value = ''; if(changed || !snapshotLoaded.value) await load() }
  catch(e) { error.value = e.message } finally {polling = false}
}
async function configure(key,value) {busy.value = true;error.value = '';try {summary.value = await api('/listening/collection',{enabled:!!summary.value.enabled,autoDownload:!!summary.value.autoDownload,[key]:value},'PUT')} catch(e){error.value=e.message} finally{busy.value=false}}
async function sync() {busy.value = true;error.value='';try {summary.value=await api('/listening/collection/sync',{})}catch(e){error.value=e.message}finally{busy.value=false}}
function create() {const name=newName.value.trim();if(!name)return;const playlist={id:'local:'+Date.now().toString(36)+Math.random().toString(36).slice(2,9),name,tracks:[]};emit('update-local',[...props.playlists,playlist]);selectedId.value=playlist.id;newName.value=''}
function remove(track) {emit('update-local',props.playlists.map(p=>p.id===selectedId.value?{...p,tracks:p.tracks.filter(t=>trackKey(t)!==trackKey(track))}:p))}
function date(value) {return value?new Date(value).toLocaleString():'尚未同步'}
onMounted(async()=>{try{await load()}catch(e){error.value=e.message}timer=setInterval(()=>{if(!document.hidden)poll()},3000)})
onUnmounted(()=>clearInterval(timer))
</script>
<template>
  <details class="account-sync"><summary><span class="sync-summary-title"><Icon name="repeat" :size="18" /><strong>QQ 账号同步</strong><span>{{!loaded?'正在读取状态…':summary.running?'正在同步…':summary.enabled?'每 10 分钟自动同步':'定时同步已暂停'}}</span></span><span class="sync-summary-time">{{loaded?'最近同步 '+date(summary.lastSuccess):'读取同步状态…'}}<Icon name="down" :size="15" /></span></summary><div class="sync-expanded"><div><p class="muted">读取我喜欢、自建及收藏歌单，可自动下载新增歌曲。本地歌单独立保存，不向 QQ 写回修改。</p><p class="muted">{{summary.running?(summary.phase||'同步中…'):'最近新增下载 '+(summary.queuedLastRun||0)+' 首'}}</p></div><div class="sync-controls"><label><input type="checkbox" :checked="summary.enabled" :disabled="busy || !loaded" @change="configure('enabled',$event.target.checked)" />定时同步</label><label><input type="checkbox" :checked="summary.autoDownload" :disabled="busy || !loaded" @change="configure('autoDownload',$event.target.checked)" />自动下载新增歌曲</label><button class="quiet" :disabled="busy || summary.running" @click="sync"><Icon name="repeat" :size="16" />{{summary.running?'同步中…':'立即同步'}}</button></div></div></details>
  <p v-if="error || syncError" class="collection-error" role="alert">{{ error || syncError }}</p>
  <div class="collection-layout"><aside class="playlist-list" aria-label="歌单列表"><form class="playlist-create" @submit.prevent="create"><input v-model="newName" maxlength="100" placeholder="新歌单名称" aria-label="新歌单名称" required /><button class="icon-button" aria-label="新建本地歌单"><Icon name="plus" /></button></form><select v-model="selectedId" class="playlist-mobile-select" aria-label="选择歌单"><option v-for="list in lists" :key="list.id" :value="list.id">{{list.name}} · {{list.tracks?.length||0}} 首</option></select><button v-for="list in lists" :key="list.id" class="playlist-item" :class="{selected:list.id===selectedId}" @click="selectedId=list.id"><Artwork :src="list.coverUrl || list.tracks?.[0]?.pic || list.tracks?.[0]?.coverUrl" /><span><strong>{{list.name}}</strong><small>{{kindLabel(list.kind)}} · {{list.tracks?.length || 0}} 首</small></span></button></aside><section class="playlist-detail" v-if="selected"><div class="playlist-heading"><Artwork class="playlist-hero-cover" :src="selected.coverUrl || selected.tracks?.[0]?.pic || selected.tracks?.[0]?.coverUrl" /><div class="playlist-hero-copy"><span class="eyebrow">{{kindLabel(selected.kind)}}</span><h2>{{selected.name}}</h2><p class="muted">{{songs.length}} 首歌曲<span v-if="selected.kind==='local'"> · 从搜索结果或播放器加入歌曲</span></p><button class="primary" :disabled="!songs.length" @click="emit('play',songs[0],songs)"><Icon name="play" :size="18" />播放全部</button></div></div><p v-if="!songs.length" class="muted">歌单还没有歌曲，去发现音乐并选择“加入歌单”。</p><input v-if="songs.length" v-model="filter" class="playlist-filter" placeholder="筛选歌单中的歌曲" aria-label="筛选歌单中的歌曲" /><div v-for="track in visibleSongs" :key="trackKey(track)" class="result-row"><button class="track-main" @click="emit('play',track,songs)"><Artwork :src="track.coverUrl" /><span><strong>{{track.title}}</strong><small>{{track.artist}} · {{track.album}}</small></span></button><button class="icon-button" :aria-label="'播放 '+track.title" @click="emit('play',track,songs)"><Icon name="play" /></button><button v-if="!track.local" class="icon-button" :aria-label="'下载 '+track.title" @click="emit('download',track)"><Icon name="download" /></button><button v-if="selected.kind==='local' && selected.id!=='local:favorites'" class="icon-button" :aria-label="'移出歌单 '+track.title" @click="remove(track)"><Icon name="close" /></button></div><button v-if="visibleSongs.length < matchingSongs.length" class="quiet" @click="showCount += 100">再显示 100 首（共 {{matchingSongs.length}} 首）</button></section></div>
</template>
<style scoped>
.playlist-mobile-select{display:none}
.account-sync{display:block!important;padding:0!important;border:1px solid var(--line)!important;border-radius:9px;background:oklch(21% .014 255)}.account-sync summary{list-style:none;cursor:pointer;display:flex;justify-content:space-between;gap:20px;padding:18px 20px;align-items:center}.account-sync summary::-webkit-details-marker{display:none}.sync-summary-title{display:flex;gap:12px;align-items:center;flex-wrap:wrap}.sync-summary-title>svg{color:var(--accent)}.sync-summary-title strong{font-weight:550;font-size:12px}.sync-summary-title>span,.sync-summary-time{font-size:10px;color:var(--muted)}.sync-summary-time{display:flex;align-items:center;gap:15px}.sync-expanded{padding:0 20px 22px;display:flex;gap:30px;justify-content:space-between}.sync-expanded .muted{font-size:11px;line-height:1.9}.playlist-heading{display:flex!important;align-items:center;gap:28px!important;margin-bottom:28px;padding:27px;background:oklch(24% .022 235);border-radius:10px;min-height:205px}.playlist-hero-cover{width:150px;box-shadow:0 14px 30px oklch(6% .01 255 / .3)}.playlist-hero-copy{display:grid;gap:14px;min-width:0}.playlist-hero-copy .eyebrow{font-size:9px}.playlist-hero-copy h2{font-size:30px!important;line-height:1.3;overflow-wrap:anywhere}.playlist-hero-copy .primary{justify-self:start;min-height:40px}.playlist-hero-copy .muted{font-size:11px}.playlist-item .artwork{border-radius:5px}.playlist-detail .playlist-filter{font-size:12px;border-radius:7px}.playlist-create input{font-size:11px!important;min-height:41px}.playlist-create{margin-bottom:12px!important}

.account-sync{display:flex;gap:32px;justify-content:space-between;border-bottom:1px solid var(--line);padding-bottom:28px}.account-sync p{max-width:65ch;margin-top:12px}.sync-controls{display:grid;gap:12px;flex-shrink:0}.sync-controls label{display:flex;gap:10px;align-items:center;font-size:13px}.sync-controls input{min-height:20px;accent-color:var(--accent)}.collection-layout{display:grid;grid-template-columns:minmax(210px,290px) minmax(0,1fr);gap:38px;margin-top:30px}.playlist-list{display:flex;flex-direction:column;gap:5px}.playlist-create{display:flex;gap:5px;margin-bottom:16px}.playlist-create input{width:100%;font-size:12px}.playlist-item{display:flex;align-items:center;gap:12px;padding:12px;border-radius:8px;text-align:left}.playlist-item.selected{background:var(--raised);color:var(--accent)}.playlist-item .artwork{width:44px}.playlist-item span{min-width:0}.playlist-item strong,.playlist-item small{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.playlist-item strong{font-size:13px}.playlist-item small{font-size:11px;color:var(--muted);margin-top:7px}.playlist-heading{display:grid;gap:16px;margin-bottom:28px}.playlist-heading h2{font-size:28px}.playlist-heading>.primary{justify-self:start}.playlist-detail{min-width:0}.playlist-filter{width:100%;margin-bottom:16px}.collection-error{color:oklch(80% .11 30);margin-top:18px}.playlist-detail .result-row .icon-button{width:36px;flex-shrink:0}@media(max-width:1000px){.collection-layout{grid-template-columns:minmax(170px,230px) minmax(0,1fr);gap:20px}}@media(max-width:760px){.account-sync{flex-direction:column;gap:22px}.sync-controls{grid-template-columns:1fr;gap:16px}.sync-controls .quiet{justify-self:start}.collection-layout{grid-template-columns:minmax(0,1fr)}.playlist-list{max-height:320px;overflow-y:auto}.playlist-heading{margin-top:16px}.playlist-detail .result-row{gap:0}.playlist-item .artwork{width:40px}}
@media(max-width:1000px){.playlist-heading{gap:20px!important;padding:23px}.playlist-hero-cover{width:110px}.playlist-hero-copy h2{font-size:25px!important}.sync-summary-time{display:none}}@media(max-width:760px){.account-sync summary{padding:17px}.sync-summary-title{gap:8px}.sync-summary-title>span{flex-basis:100%;margin-left:26px;font-size:9px}.sync-expanded{flex-direction:column;padding-inline:17px;gap:15px}.collection-layout{gap:20px;margin-top:22px}.playlist-list{display:flex;flex-direction:row;flex-wrap:wrap;max-height:none;overflow:visible;gap:7px}.playlist-create{width:100%;margin-bottom:7px!important}.playlist-item{width:calc(50% - 4px);padding:9px;gap:9px}.playlist-item strong{font-size:11px}.playlist-item small{font-size:8px;line-height:1.6}.playlist-item .artwork{width:34px}.playlist-heading{padding:18px;gap:18px!important;min-height:175px;margin-top:5px}.playlist-hero-cover{width:95px}.playlist-hero-copy{gap:10px}.playlist-hero-copy h2{font-size:22px!important}.playlist-hero-copy .eyebrow{font-size:8px}.playlist-hero-copy .muted{font-size:9px}.playlist-hero-copy .primary{font-size:10px;min-height:36px;padding-inline:14px}}
@media(max-width:760px){.playlist-mobile-select{display:block;width:100%;font-size:12px;min-height:44px}.playlist-item{display:none}.playlist-list{gap:10px}}
</style>
